require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; requireLogin();$id=filter_input(INPUT_POST,'id_pesanan',FILTER_VALIDATE_INT);$file=$_FILES['bukti']??null;if(!$id||!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>5242880)exit('Bukti pembayaran tidak valid atau melebihi 5MB.');$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!isset($allowed[$mime]))exit('Format bukti harus JPG, PNG, atau PDF.');$dir=__DIR__.'/assets/bukti_transfer';if(!is_dir($dir))mkdir($dir,0755,true);$name='bukti_'.$id.'_'.bin2hex(random_bytes(5)).'.'.$allowed[$mime];$path='assets/bukti_transfer/'.$name;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))exit('Upload gagal.');$q=$pdo->prepare('SELECT total,id_produk FROM pesanan WHERE id_pesanan=:id AND id_user=:user');$q->execute(['id'=>$id,'user'=>$_SESSION['id_user']]);$order=$q->fetch();if(!$order)exit('Pesanan tidak ditemukan.');$s=$pdo->prepare("INSERT INTO pembayaran (id_produk,id_user,id_pesanan,bukti_pembayaran,metode_pembayaran,total_harga,status_tf,waktu) VALUES (:product,:user,:order,:proof,'Transfer Bank',:total,'menunggu',CURTIME())");$s->execute(['product'=>$order['id_produk'],'user'=>$_SESSION['id_user'],'order'=>$id,'proof'=>$path,'total'=>$order['total']]);$pdo->prepare("UPDATE pesanan SET status='menunggu_verifikasi' WHERE id_pesanan=:id")->execute(['id'=>$id]);redirect('pesanan.php?baru=1');